pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(uint160(logAddr) != 0);
        c.SetLogFile(logAddr);
        assertTrue(address(c.Log()) == logAddr);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function depositCredit(address /*unused*/) external {
        uint amount = 1 ether;
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint _val) public {
        c.SetMinSum(_val);
        assert(c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function test(uint amount) public
    {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Deposit{value: amount}();

        uint balBefore = c.balances(address(this));
        uint ethBefore = address(this).balance;

        c.Collect(amount);

        assert(c.balances(address(this)) == balBefore - amount
               && address(this).balance >= ethBefore + amount);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function runTest(uint _a, uint _b) public
    {
        c.SetMinSum(_a);
        c.SetMinSum(_b);
        assert(c.MinSum() == _b);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint s, uint _val) public payable {
        require(c.MinSum() == s);
        require(s != 0);
        require(s + _val > s);
        c.SetMinSum(_val);
        assert(c.MinSum() == _val);
    }
    receive() external payable {}
}
